    <g>
      ${[...Array(16)].map(()=>{const x=60+rnd()*260,y=240+rnd()*90;return `<circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="${(rnd()*2.2+.7).toFixed(1)}" fill="${rnd()>.5?a:'#fff'}" opacity="${(.2+rnd()*.6).toFixed(2)}"/>`}).join('')}
