410: export function openPack(packId) {
411:   ensureToday();
412:   const today = todayKey();
413:   let pack;
414:   if (packId === 'potd') {
415:     pack = getPackOfTheDay(new Date());
416:     if (state.potd.purchases >= 3) throw gameError('POTD_LIMIT', 'Daily limit reached for Pack of the Day');
417:   } else {
418:     pack = PACK_MAP[packId];
419:   }
420:   if (!pack) throw gameError('NO_PACK', 'Unknown pack');
421:   if (pack.oncePerDay && state.dailyPackDate === today) throw gameError('DAILY_USED', 'Daily Pack already claimed today');
422:   if (packId === 'potd' && state.coins < pack.cost && !state.tokens.includes('potd')) {
423:     throw gameError('NOT_ENOUGH_COINS', 'Not enough coins');
424:   }
425: 
426:   let usedToken = false;
427:   const tokenIdx = state.tokens.indexOf(packId);
428:   if (tokenIdx >= 0 && packId !== 'potd') {
429:     state.tokens.splice(tokenIdx, 1);
430:     usedToken = true;
431:     state.tokensUsed++;
432:   } else {
433:     spendCurrency(pack.currency, pack.cost);
434:   }
435: 
436:   const pulls = generatePull(pack);
437:   const results = [];
438:   for (const p of pulls) {
439:     const item = addItem(p.card.id, p.finish, {serial: p.serial, source: packId});
440:     const value = cardValue(p.card, p.finish);
441:     results.push({...p, item, value});
442:     state.stats.cardsPulled++;
443:     if (p.isNew) { state.daily.newCards++; }
444:     if (RANK[p.card.rarity] >= 2) state.stats.epicPulls++;
445:     if (RANK[p.card.rarity] >= 2) state.daily.epicPulls++;
446:     if (RANK[p.card.rarity] >= 3) { state.stats.legendaryPulls++; state.daily.legendaryPulls++; }
447:     if (RANK[p.card.rarity] >= 4) state.stats.iconicPulls++;
448:     state.recentPulls.unshift({cardId: p.card.id, finish: p.finish, serial: p.serial, isNew: p.isNew, at: Date.now()});
449:   }
450:   state.recentPulls = state.recentPulls.slice(0, 24);
451:   state.stats.packsOpened++;
452:   state.daily.packsOpened++;
453:   if (pack.oncePerDay) state.dailyPackDate = today;
454:   if (packId === 'daily') { state.stats.dailyPacks++; state.daily.dailyPacks++; }
455:   if (packId === 'gold' || packId === 'f1-gold' || packId === 'motogp-gold') { state.stats.goldPacks++; state.daily.goldPacks++; }
456:   if (packId === 'potd') state.potd.purchases++;
457:   const xpGain = 30 + results.reduce((s, r) => s + (r.isNew ? 12 : 2) + ({common:0,rare:2,epic:8,legendary:18,iconic:45}[r.card.rarity] || 0), 0);
458:   const levelUps = addXp(xpGain);
459:   if (state.stats.maxUnique < uniqueCount()) state.stats.maxUnique = uniqueCount();
460:   save(); emit();
461:   return {pack, results, usedToken, currency: pack.currency, amount: pack.cost, levelUps, xpGain};
462: }
