75: export function localDateKey(date = new Date()) {
76:   const y = date.getFullYear();
77:   const m = String(date.getMonth() + 1).padStart(2, '0');
78:   const d = String(date.getDate()).padStart(2, '0');
79:   return `${y}-${m}-${d}`;
80: }
81: 
82: export function dateSeed(date = new Date()) {
83:   return parseInt(localDateKey(date).replace(/-/g, ''), 10);
84: }
