32:   const g = Math.round(A.g + (B.g - A.g) * t);
33:   const bl = Math.round(A.b + (B.b - A.b) * t);
34:   return `#${[r,g,bl].map(v => v.toString(16).padStart(2,'0')).join('')}`;
35: }
36: function lum(hex) {
37:   const c = hexToRgb(hex);
38:   return (c.r * .299 + c.g * .587 + c.b * .114) / 255;
39: }
40: const dark = (hex, amt = .68) => mix(hex, '#05060a', amt);
41: const light = (hex, amt = .3) => mix(hex, '#ffffff', amt);
42: const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
