162: function bgScene(card, id, finish) {
163:   const rnd = mulberry(hashStr(card.id + card.name));
164:   const [p, s, a] = card.colors;
165:   const variant = hashStr(card.id) % 4;
166:   const isDark = lum(p) < .25;
167:   let out = `<rect width="360" height="504" fill="url(#${id}-bg)"/>
168:     <rect width="360" height="504" fill="url(#${id}-glow)"/>`;
169:   // big diagonal color block
170:   out += `<g opacity="${.9}">
171:     <polygon points="0,${90+variant*17} 360,${30+variant*12} 360,${190+variant*14} 0,${250+variant*9}" fill="${rgba(p,.18)}"/>
172:     <polygon points="0,${190+variant*14} 360,${120+variant*10} 360,${310+variant*8} 0,${380+variant*6}" fill="${rgba(a,.07)}"/>
173:   </g>`;
174:   if (variant === 0) {
175:     out += `<circle cx="298" cy="118" r="152" fill="none" stroke="${rgba(a,.14)}" stroke-width="1"/>
176:       <circle cx="298" cy="118" r="118" fill="none" stroke="${rgba(a,.1)}" stroke-width="1"/>
177:       <circle cx="298" cy="118" r="84" fill="none" stroke="${rgba(a,.08)}" stroke-width="1"/>`;
178:   } else if (variant === 1) {
179:     out += `<rect y="280" width="360" height="140" fill="url(#${id}-grid)" opacity=".8"/>`;
180:   } else if (variant === 2) {
181:     out += `<g stroke="${rgba('#fff',.08)}" stroke-width="1">
182:       <path d="M-20 390L380 190M-20 440L380 240M-20 490L380 290M40 504L420 258M90 504L450 238"/></g>`;
183:   } else {
184:     out += `<path d="M-30 360C70 300 140 300 220 330S340 370 400 310" fill="none" stroke="${rgba(a,.16)}" stroke-width="46"/>
185:       <path d="M-30 360C70 300 140 300 220 330S340 370 400 310" fill="none" stroke="${rgba('#fff',.1)}" stroke-width="1.5" stroke-dasharray="16 12"/>`;
186:   }
187:   // speed streaks
188:   for (let i = 0; i < 7; i++) {
189:     const y = 80 + rnd() * 200;
190:     const w = 100 + rnd() * 190;
191:     out += `<rect x="${320 - w}" y="${y}" width="${w}" height="${rnd() > .65 ? 2 : 1}" fill="url(#${id}-streak)" opacity="${.15 + rnd() * .25}"/>`;
192:   }
193:   // bokeh
194:   for (let i = 0; i < 7; i++) {
195:     const cx = 20 + rnd() * 330, cy = 30 + rnd() * 290, r = 1 + rnd() * 4;
196:     out += `<circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="${r.toFixed(1)}" fill="${i % 2 ? a : '#fff'}" opacity="${(.1 + rnd() * .3).toFixed(2)}"/>`;
197:   }
198:   if (finish === 'holo') {
199:     out += `<g opacity=".2">${[...Array(9)].map((_,i) => `<polygon points="180,190 360,${-40+i*56} 360,${-10+i*56}" fill="${['#ff5ac8','#ffd166','#65ffc8','#60c8ff','#b17dff'][i%5]}"/>`).join('')}</g>`;
200:   }
201:   return out;
202: }
