293: let fxCanvas = null;
294: let fxCtx = null;
295: let particles = [];
296: let fxRaf = 0;
297: export function initFx() {
298:   fxCanvas = document.getElementById('fx');
299:   if (!fxCanvas) return;
300:   fxCtx = fxCanvas.getContext('2d');
301:   resizeFx();
302:   window.addEventListener('resize', resizeFx);
303: }
304: function resizeFx() {
305:   if (!fxCanvas) return;
306:   const dpr = Math.min(2, window.devicePixelRatio || 1);
307:   fxCanvas.width = Math.floor(innerWidth * dpr);
308:   fxCanvas.height = Math.floor(innerHeight * dpr);
309:   fxCanvas.style.width = innerWidth + 'px';
310:   fxCanvas.style.height = innerHeight + 'px';
311:   if (fxCtx) fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
312: }
313: export function burst(color = '#ffc247', amount = 80, power = 1) {
314:   if (!fxCtx) return;
315:   const cx = innerWidth / 2, cy = innerHeight * 0.46;
316:   const palette = color === 'iconic'
317:     ? ['#ff66d8', '#ffe27a', '#65ffc8', '#5ad0ff', '#b17dff']
318:     : color === 'legendary'
319:       ? ['#ffc247', '#ffe8a8', '#ff9b30', '#ffffff']
320:       : [color, '#ffffff', '#ffd166'];
321:   for (let i = 0; i < amount; i++) {
322:     const ang = Math.random() * Math.PI * 2;
323:     const sp = (2.5 + Math.random() * 8) * power;
324:     particles.push({
325:       x: cx, y: cy,
326:       vx: Math.cos(ang) * sp,
327:       vy: Math.sin(ang) * sp - 2,
328:       size: 2 + Math.random() * 5,
329:       life: 1,
330:       decay: .008 + Math.random() * .012,
331:       color: palette[Math.floor(Math.random() * palette.length)],
332:       rot: Math.random() * 6,
333:       vr: (Math.random() - .5) * .3,
334:       shape: Math.random() > .55 ? 'line' : 'rect',
335:     });
336:   }
337:   if (!fxRaf) fxRaf = requestAnimationFrame(drawFx);
338: }
339: function drawFx() {
340:   if (!fxCtx) return;
341:   fxCtx.clearRect(0, 0, innerWidth, innerHeight);
342:   particles = particles.filter(p => p.life > 0);
343:   for (const p of particles) {
344:     p.x += p.vx; p.y += p.vy;
345:     p.vy += .13; p.vx *= .994; p.vy *= .994;
346:     p.life -= p.decay;
347:     p.rot += p.vr;
348:     fxCtx.save();
349:     fxCtx.globalAlpha = Math.max(0, p.life);
350:     fxCtx.fillStyle = p.color;
351:     fxCtx.translate(p.x, p.y);
352:     fxCtx.rotate(p.rot);
353:     if (p.shape === 'line') fxCtx.fillRect(-p.size * 2, -1, p.size * 4, 2);
354:     else fxCtx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
355:     fxCtx.restore();
356:   }
357:   if (particles.length) fxRaf = requestAnimationFrame(drawFx);
358:   else { fxRaf = 0; fxCtx.clearRect(0, 0, innerWidth, innerHeight); }
359: }
