307: export function collectionScreen() {
308:   const s = getState();
309:   const f = view.collection;
310:   const grouped = groupedCollection();
311:   const byId = new Map(grouped.map(g => [g.card.id, g]));
312:   const itemsById = new Map();
313:   for (const item of s.items) {
314:     if (!itemsById.has(item.cardId)) itemsById.set(item.cardId, []);
315:     itemsById.get(item.cardId).push(item);
316:   }
317:   let cards = f.mode === 'all' ? [...CARDS] : grouped.map(g => g.card);
318:   if (f.sport !== 'all') cards = cards.filter(c => c.sport === f.sport);
319:   if (f.rarity !== 'all') cards = cards.filter(c => c.rarity === f.rarity);
320:   if (f.type !== 'all') cards = cards.filter(c => c.type === f.type);
321:   if (f.q) {
322:     const q = f.q.toLowerCase().trim();
323:     cards = cards.filter(c => c.searchable.includes(q));
324:   }
325:   const sorters = {
326:     recent: (a, b) => {
327:       const ga = byId.get(a.id), gb = byId.get(b.id);
328:       const ta = ga ? Math.max(...ga.items.map(i => i.at || 0)) : 0;
329:       const tb = gb ? Math.max(...gb.items.map(i => i.at || 0)) : 0;
330:       return tb - ta || a.name.localeCompare(b.name);
331:     },
332:     rarity: (a, b) => RARITY_ORDER[b.rarity] - RARITY_ORDER[a.rarity] || a.name.localeCompare(b.name),
333:     name: (a, b) => a.name.localeCompare(b.name),
334:     value: (a, b) => {
335:       const ga = byId.get(a.id), gb = byId.get(b.id);
336:       const va = ga ? cardValue(a, ga.best) * ga.count : 0;
337:       const vb = gb ? cardValue(b, gb.best) * gb.count : 0;
338:       return vb - va;
339:     },
340:     copies: (a, b) => (byId.get(b.id)?.count || 0) - (byId.get(a.id)?.count || 0) || a.name.localeCompare(b.name),
341:   };
342:   cards.sort(sorters[f.sort] || sorters.recent);
343:   const groupsBySport = {};
344:   for (const c of cards) (groupsBySport[c.sport] ||= []).push(c);
345:   const dupes = grouped.filter(g => g.count > 1);
346:   const fav = CARD_MAP[s.favorite];
347:   const completion = Math.round(uniqueCount() / CARD_COUNT * 100);
348:   const milestones = achievements().filter(a => a.kind === 'unique');
349: 
350:   return `<div class="screen" data-screen="collection">
351:     <div class="page-head">
352:       <div>
353:         <div class="eyebrow">The vault · ${completion}% complete</div>
354:         <h1 class="page-title">My <em>collection</em></h1>
355:         <p class="page-sub">${uniqueCount()} unique cards across Formula 1, MotoGP and the crossover legends. Every copy, finish and numbered edition is archived here.</p>
356:       </div>
357:       <div class="page-head-actions">
358:         <button class="btn btn-sm ${f.mode === 'vault' ? 'btn-primary' : ''}" data-collection-mode="vault">My vault</button>
359:         <button class="btn btn-sm ${f.mode === 'all' ? 'btn-primary' : ''}" data-collection-mode="all">All cards</button>
360:         <button class="btn btn-sm ${dupes.length ? '' : 'hidden'}" data-sell-dupes>Duplicates ${dupes.length ? `(${dupes.length})` : ''}</button>
361:       </div>
362:     </div>
363: 
364:     <div class="coll-stats">
365:       ${statBox('Unique cards', `${uniqueCount()}<small>/${CARD_COUNT}</small>`, 'Vault completion', 'gold')}
366:       ${statBox('Total copies', s.items.length, `${dupes.length} duplicate groups`, 'cyan')}
367:       ${statBox('Vault value', `◈ ${fmt(collectionValue())}`, 'Collector valuation', 'green')}
368:       ${statBox('Packs opened', s.stats.packsOpened, `${s.stats.iconicPulls} iconic pulled`, 'red')}
369:       ${statBox('Favourite', fav ? esc(fav.name.split(' ').pop()) : '—', fav ? esc(fav.team || 'No team') : 'Set one in card details')}
370:     </div>
371: 
372:     <div class="collection-milestones">
373:       ${milestones.map(a => `<div class="cm-item ${a.completed ? 'done' : ''}"><span class="cm-ic">${a.completed ? '✓' : a.goal}</span><b>${a.goal} unique</b><span class="cm-r">${rewardText(a.reward)}</span></div>`).join('')}
374:     </div>
375: 
376:     <div class="coll-filter">
377:       <div class="field"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg><input id="coll-search" data-filter="search" placeholder="Search driver, team, era, moment…" value="${esc(f.q)}" autocomplete="off" /></div>
378:       <select class="select" data-filter="sport" aria-label="Sport">
379:         ${option('all', 'All sports', f.sport)}${option('f1', 'Formula 1', f.sport)}${option('motogp', 'MotoGP', f.sport)}${option('crossover', 'Crossover', f.sport)}
380:       </select>
381:       <select class="select" data-filter="rarity" aria-label="Rarity">
382:         ${option('all', 'All rarities', f.rarity)}${Object.entries(RARITY).reverse().map(([k, v]) => option(k, v.label, f.rarity)).join('')}
383:       </select>
384:       <select class="select" data-filter="type" aria-label="Card type">
385:         ${option('all', 'All types', f.type)}${Object.entries({driver:'Drivers / Riders', team:'Constructors', car:'Cars', bike:'Bikes', moment:'Moments'}).map(([k, v]) => option(k, v, f.type)).join('')}
386:       </select>
387:       <select class="select" data-filter="sort" aria-label="Sort">
388:         ${option('recent', 'Newest first', f.sort)}${option('rarity', 'Rarity', f.sort)}${option('value', 'Value', f.sort)}${option('copies', 'Duplicates', f.sort)}${option('name', 'Name A–Z', f.sort)}
389:       </select>
390:       <span class="coll-count">${cards.length} ${f.mode === 'all' ? 'cards' : 'own cards'}</span>
391:     </div>
392: 
393:     ${cards.length ? SPORT_ORDER.filter(sp => groupsBySport[sp]?.length).map(sp => {
394:       const sportCards = groupsBySport[sp];
395:       const owned = f.mode === 'all' ? sportCards.filter(c => byId.has(c.id)).length : sportCards.length;
396:       const total = f.mode === 'all' ? sportCards.length : CARDS.filter(c => c.sport === sp).length;
397:       return `<div class="coll-group-title">${SPORT_LABEL[sp]} <span class="cnt">${owned} / ${total} ${f.mode === 'all' ? 'collected' : 'shown'}</span></div>
398:       <div class="card-grid">
399:         ${sportCards.map(card => {
400:           const g = byId.get(card.id);
401:           if (!g && f.mode === 'vault') return '';
402:           if (!g) return `<div data-open-card="${esc(card.id)}">${slotHTML(card)}</div>`;
403:           const best = g.items.find(i => i.finish === g.best) || g.items[0];
404:           return cardHTML(card, { finish: g.best, serial: best?.serial, count: g.count, itemUid: best?.uid });
405:         }).join('')}
406:       </div>`;
407:     }).join('') : emptyState('▤', 'No cards match those filters', 'Try widening the search or switching to All cards.', `<button class="btn btn-sm" data-collection-clear>Clear filters</button>`)}
408:   </div>`;
409: }
