/* ============ PACKS ============ */
.pack{
  position:relative;aspect-ratio:100/146;width:100%;border-radius:10px;overflow:hidden;container-type:inline-size;
  background:linear-gradient(160deg,var(--p1,#ff2f38),var(--p2,#7d0d16) 70%);
  box-shadow:0 30px 55px -22px rgba(0,0,0,.9), inset 0 1px 0 rgba(255,255,255,.4), 0 0 0 1px rgba(0,0,0,.5);
  transform-style:preserve-3d;transition:transform .4s cubic-bezier(.2,.8,.2,1), box-shadow .4s;
  isolation:isolate;cursor:pointer;
}
.pack:hover{transform:translateY(-6px) rotateX(2deg) rotateY(-3deg);box-shadow:0 40px 70px -25px #000, 0 0 46px -10px var(--p3,rgba(255,47,56,.5)), inset 0 1px 0 rgba(255,255,255,.5)}
.pack::before{content:'';position:absolute;inset:0;z-index:1;background:
  repeating-linear-gradient(115deg,transparent 0 9%, rgba(255,255,255,.05) 9.5% 10%, transparent 10.5% 19%),
  radial-gradient(ellipse at var(--gx,70%) var(--gy,20%), var(--p3,rgba(255,69,80,.75)), transparent 55%),
  linear-gradient(160deg, rgba(255,255,255,.14), transparent 30%, rgba(0,0,0,.4) 100%)}
.pack::after{content:'';position:absolute;inset:0;z-index:6;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.42) 46%,rgba(255,255,255,.05) 50%,transparent 62%);transform:translateX(-130%) skewX(-12deg);animation:packSheen 7s ease-in-out infinite;pointer-events:none}
.pack-crimp{position:absolute;left:0;right:0;height:5.5%;z-index:4;background:
  repeating-linear-gradient(90deg, rgba(0,0,0,.35) 0 2px, rgba(255,255,255,.22) 2px 4px, rgba(0,0,0,.2) 4px 6px),
  linear-gradient(180deg, #d7dce5, #7b8494 60%, #aeb7c4);
  box-shadow:0 2px 6px rgba(0,0,0,.45)}
.pack-crimp.top{top:0;border-bottom:1px solid rgba(0,0,0,.4)}
.pack-crimp.bottom{bottom:0;border-top:1px solid rgba(0,0,0,.4)}
.pack-inner{position:absolute;inset:5.5% 0;z-index:3;padding:8% 8% 7%;display:flex;flex-direction:column;overflow:hidden}
.pack-brand{display:flex;align-items:center;justify-content:space-between;font-family:var(--font-tech);font-weight:700;font-size:2.35cqw;letter-spacing:.24em;color:rgba(255,255,255,.7);text-transform:uppercase;position:relative;z-index:3}
