473:       ${[...Array(4)].map(()=>{const x=30+rnd()*300,y=180+rnd()*120;return `<path d="M${x.toFixed(0)} ${y.toFixed(0)}l${(20+rnd()*40).toFixed(0)} ${(rnd()*8-4).toFixed(0)}" stroke="${rgba(a,.4)}" stroke-width="${(rnd()*1.5+.5).toFixed(1)}"/>`}).join('')}
474:     </g>
475:     <g opacity=".5"><path d="M60 360c60-20 180-20 240 0" fill="none" stroke="${rgba('#fff',.15)}" stroke-width="1" stroke-dasharray="8 10"/></g>
