  let out = `<g transform="translate(${dx},0)">
    <ellipse cx="185" cy="400" rx="150" ry="58" fill="${rgba(p,.28)}" filter="url(#${id}-soft)"/>
    <!-- shoulders -->
    <path d="M28 504c14-83 58-127 108-140l30-6h38l30 6c50 13 94 57 108 140z" fill="url(#${id}-suit)"/>
    <path d="M58 504c10-65 44-103 92-117l-20 117z" fill="${rgba(p,.55)}"/>
