content.text:
.app-shell{min-height:100vh}
.topbar{
  position:fixed;top:0;left:0;right:0;height:var(--header-h);z-index:60;
  display:flex;align-items:center;gap:18px;padding:0 20px;
  background:linear-gradient(180deg, rgba(10,12,16,.96), rgba(9,11,15,.88));
  border-bottom:1px solid var(--line);backdrop-filter:blur(18px);
  box-shadow:0 18px 40px -30px #000;
}
.brand{display:flex;align-items:center;gap:10px;padding:0;flex-shrink:0}
.brand-mark{width:35px;height:35px;color:var(--red);filter:drop-shadow(0 0 12px rgba(255,47,56,.5))}
.brand-mark svg{width:100%;height:100%}
.brand-type{position:relative;display:flex;flex-direction:column;text-align:left;font-family:var(--font-display);font-weight:800;font-size:23px;line-height:.82;letter-spacing:.06em;padding-top:1px}
.brand-type>span{display:inline-block;color:#fff}
.brand-type>span>span{color:var(--red)}
.brand-type small{font-family:var(--font-tech);font-weight:600;font-size:8px;letter-spacing:.36em;color:var(--dim);margin-top:5px}
.topbar-mid{flex:1;display:flex;justify-content:center}
.season-pill{display:flex;align-items:center;gap:9px;font-family:var(--font-tech);font-weight:600;font-size:11px;letter-spacing:.2em;color:var(--muted);border:1px solid var(--line);background:rgba(255,255,255,.025);padding:7px 14px;border-radius:99px}
.season-pill .dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 10px var(--green);animation:pulse 2.5s infinite}
.season-pill .sep{width:1px;height:10px;background:var(--line-2)}
#daily-clock{color:#cfd6e2;font-variant-numeric:tabular-nums;letter-spacing:.1em}
.topbar-right{display:flex;align-items:center;gap:10px}
.wallet{display:flex;gap:7px}
.currency{display:flex;align-items:center;gap:7px;height:36px;padding:0 5px 0 11px;border-radius:10px;border:1px solid var(--line);background:linear-gradient(180deg,#141821,#0e1117);position:relative;overflow:hidden}
.currency::after{content:'';position:absolute;inset:0;background:linear-gradient(120deg, transparent 30%, rgba(255,255,255,.05) 45%, transparent 60%)}
.currency-ico{font-size:15px;line-height:1}
.currency.coin .currency-ico{color:var(--gold);text-shadow:0 0 10px rgba(246,196,83,.5)}
.currency.gem .currency-ico{color:var(--cyan);text-shadow:0 0 10px rgba(34,211,238,.5)}
.currency-val{font-family:var(--font-tech);font-weight:700;font-size:15px;letter-spacing:.02em;min-width:26px;font-variant-numeric:tabular-nums}
.currency-plus{width:24px;height:24px;border-radius:7px;background:rgba(255,255,255,.07);display:grid;place-items:center;font-size:14px;color:var(--muted);transition:.2s}
.currency-plus:hover{background:var(--red);color:#fff}
.level-chip{display:flex;align-items:center;gap:8px;height:36px;padding:0 11px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.025)}
.level-chip .lvl{font-family:var(--font-tech);font-weight:700;font-size:11px;letter-spacing:.12em;color:var(--gold);white-space:nowrap}
.level-chip .lvl i{font-style:normal;margin-left:2px}
.xpbar{width:42px;height:4px;background:rgba(255,255,255,.1);border-radius:3px;overflow:hidden}
.xpbar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--gold-2),var(--gold));border-radius:3px;transition:width .5s}
.icon-btn{width:36px;height:36px;border:1px solid var(--line);border-radius:10px;display:grid;place-items:center;color:var(--muted);background:rgba(255,255,255,.02);transition:.2s}
.icon-btn:hover{color:var(--text);border-color:var(--line-2);background:rgba(255,255,255,.05)}
.icon-btn svg{width:18px;height:18px}
#sound-toggle .ico-off{display:none}
body.muted #sound-toggle .ico-off{display:block}
body.muted #sound-toggle .ico-on{display:none}

.sidebar{
  position:fixed;top:var(--header-h);bottom:0;left:0;width:var(--side-w);z-index:50;
  display:flex;flex-direction:column;padding:18px 12px 14px;
  background:linear-gradient(180deg, rgba(12,14,19,.9), rgba(8,10,14,.92));
  border-right:1px solid var(--line);backdrop-filter:blur(14px);
}
.nav-main{display:flex;flex-direction:column;gap:3px}
.nav-item{
  display:flex;align-items:center;gap:11px;height:42px;padding:0 12px;border-radius:10px;
.pity-sub button{font-family:var(--font-tech);font-size:10px;color:var(--cyan);letter-spacing:.04em}
.nav-small{height:34px;font-size:11px;opacity:.65}
.nav-small:hover{opacity:1}

.main{
  margin-left:var(--side-w);padding:calc(var(--header-h) + 24px) 28px 90px;
  min-height:100vh;position:relative;
}
.screen{max-width:1440px;margin:0 auto;animation:screenIn .45s cubic-bezier(.2,.8,.2,1) both}
.mobile-nav{display:none}

