      <g transform="translate(90,40) scale(.58) rotate(-7 180 300)" opacity=".55">
        ${isBike ? bikeShape(id, [dark(p,.25),s,a], '') : carShape(id, [dark(p,.3),s,dark(a,.2)], card.era, '')}
      </g>
      <g transform="translate(-18,42) scale(.9)">
        ${isCross ? bikeShape(id, [s,p,a], card.number ?? '') : isBike ? bikeShape(id, card.colors, card.number ?? '') : carShape(id, card.colors, card.era, card.number ?? '')}
